fn solve(n: i8) -> bool {
    debug_assert!(n >= 1 && n <= 99);

    // Case 1: n < 12
    if n < 12 {
        return !matches!(n, 1 | 7 | 9 | 10 | 11);
    }

    // Case 2: 12 < n < 30
    if n > 12 && n < 30 {
        return false;
    }

    // Case 3: 69 < n < 80
    if n > 69 && n < 80 {
        return false;
    }

    // Case 4: n > 89
    if n > 89 {
        return false;
    }

    // Remaining: n == 12, or 30..=69, or 80..=89
    let last_digit = n % 10;
    !matches!(last_digit, 1 | 7 | 9)
}